describe('AC2 checkStory: no whole-tree verification', () => {
  it('checkStory_afterWaveCommitAndDocEdits_skipsWhileWholeTreeVerifyReceiptFails', () => {
    // The AC5 fixture: commit a wave, edit docs, resume. Whole-tree verification must be provably unusable here.
    const t = makeRepo();
    for (const s of t.stories) { s.status = '[>]'; s.tick = ' '; }
    t.writeTodo();
    t.commit('start wave');
    t.write('src/a.js', '// a implemented\n');
    const preWave = gr.treeSnapshot(t.root);
    expect(preWave.ok, preWave.reason).toBe(true);
    const checkpointBeforeMarking = entry(t, 'F-1.1');
    gr.writeReceipt(t.root, {
      schema: gr.RECEIPT_SCHEMA, id: RID, status: 'passed', exitCode: 0, mode: 'full', changedOnly: false,
      head: gr.headSha(t.root), treeHashStart: preWave.hash, treeHashEnd: preWave.hash,
      build: { status: 'passed' }, projects: [],
    });
    t.history([record(RID)]);
    t.story('F-1.1').status = '[x]'; t.story('F-1.1').tick = 'x';
    t.writeTodo();
    t.write('docs/.output/plans/261118-1200-run-todo-fixture.md', waveLog(line(checkpointBeforeMarking)));
    t.commit('wave 1: F-1.1');
    t.write('docs/notes.md', 'docs edited after the wave commit\n');
    t.write('docs/.output/handoffs/h.md', 'handoff\n');
    t.story('F-1.2').status = '[>]';
    t.writeTodo();
    t.write('docs/.output/plans/261118-1200-run-todo-fixture.md', `${waveLog(line(checkpointBeforeMarking))}\n## Resume Point\nnext: F-1.2\n`);

    expect(gr.verifyReceiptForRoot({ root: t.root, mode: 'full' }).ok).toBe(false);
    const plan = fs.readFileSync(path.join(t.root, 'docs/.output/plans/261118-1200-run-todo-fixture.md'), 'utf8');
    expect(verdict(t, plan, 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_withNoGateReceiptFileAtAll_stillSkipsFromHistoryAlone', () => {
    const t = makeRepo();
    expect(fs.existsSync(gr.receiptPath(t.root))).toBe(false);
    expect(verdict(t, arm(t, ['F-1.1']), 'F-1.1').decision).toBe('skip');
  });
});

