// ── AC4: reuse of plan-check and gate-receipt, no second engine ──

describe('AC4 no copied extraction and no second reuse engine', () => {
  const stripComments = (text) => text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"`])\/\/.*$/gm, '$1');
  const source = () => stripComments(fs.readFileSync(SCRIPT, 'utf8'));

  it('source_importsStoryBlockFromPlanCheckAndDoesNotDefineIt', () => {
    const text = source();
    expect(text).toMatch(/require\(\s*['"]\.\/plan-check(?:\.js)?['"]\s*\)/);
    expect(text).toMatch(/\bstoryBlock\b/);
    expect(text).not.toMatch(/function\s+storyBlock\b|\bstoryBlock\s*=\s*(?:function|\()/);
  });

  it('source_usesGateReceiptEngineAndDefinesNoSecondOne', () => {
    const text = source();
    expect(text).toMatch(/require\(\s*['"]\.\/_lib\/gate-receipt(?:\.js)?['"]\s*\)/);
    for (const name of ['treeSnapshot', 'hashFiles', 'decideReuse']) {
      expect(text, `uses ${name}`).toMatch(new RegExp(`\\b${name}\\b`));
      expect(text, `does not redefine ${name}`).not.toMatch(new RegExp(`function\\s+${name}\\b|\\b${name}\\s*=\\s*(?:function|\\()`));
    }
  });

  it('source_neverCallsWholeTreeVerifyReceipt', () => {
    const text = source();
    expect(text).not.toMatch(/verifyReceiptForRoot|verify-receipt|checkReceiptForPr/);
  });

  it('source_exportsTheNamedApiAndIsRequirableWithoutRunningTheCli', () => {
    const mod = sc();
    for (const name of ['hashStory', 'parseCheckpoints', 'checkStory', 'main']) expect(typeof mod[name], name).toBe('function');
  });
});

