const planFor = (t, id, rid = RID) => waveLog(line(entry(t, id, rid)));

describe('F3: a story whose Files the hash cannot see reruns, never skips', () => {
  it('checkStory_proseOnlyFilesAndASourceEdit_reruns', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['the main source file a in src'] }]);
    t.writeTodo();
    const plan = arm(t, ['F-1.1']);
    t.write('src/a.js', '// a edited\n');
    expect(verdict(t, plan, 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED', stale: false });
  });

  it('checkStory_proseOnlyFilesAndNothingEdited_stillReruns', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['the main source file a in src'] }]);
    t.writeTodo();
    const result = verdict(t, arm(t, ['F-1.1']), 'F-1.1');
    expect(result).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
    expect(result.reason).toContain('F-1.1');
  });

  it('checkStory_filesFieldWithNoEntries_reruns', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: [] }]);
    t.writeTodo();
    expect(verdict(t, arm(t, ['F-1.1']), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
  });

  it('checkStory_noFilesFieldAtAll_reruns', () => {
    const t = makeRepo();
    const bare = t.todo().replace(/ {2}\* \*\*Files:\*\*\n {4}\* `src\/a\.js`\n/, '');
    expect(bare).not.toBe(t.todo());
    fs.writeFileSync(t.todoPath, bare);
    expect(verdict(t, arm(t, ['F-1.1']), 'F-1.1', bare)).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
  });

  it('checkStory_partiallyResolvedFiles_aPathPlusAProseEntry_reruns', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['src/a.js', 'its test'] }]);
    t.writeTodo();
    expect(verdict(t, arm(t, ['F-1.1']), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
  });

  // The fixture wraps each entry in backticks, so two bullets are joined into one multi-path bullet by hand.
  const joinedBullet = t => {
    t.writeTodo();
    const joined = t.todo().replace('    * `src/a.js`\n    * `src/b.js`\n', '    * `src/a.js`, `src/b.js`\n');
    expect(joined).not.toBe(t.todo());
    fs.writeFileSync(t.todoPath, joined);
  };

  it('checkStory_oneBulletListingTwoPaths_isResolvedAndSkips', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['src/a.js', 'src/b.js'] }]);
    joinedBullet(t);
    expect(verdict(t, arm(t, ['F-1.1']), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_secondPathOfAMultiPathBulletEdited_isStaleGreen', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['src/a.js', 'src/b.js'] }]);
    joinedBullet(t);
    const plan = arm(t, ['F-1.1']);
    t.write('src/b.js', '// b edited\n');
    expect(verdict(t, plan, 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'STALE_GREEN', stale: true });
  });

  it('checkStory_proseOnlyFilesButTheBlockChanged_isStillReportedAsAStaleGreen', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['the main source file a in src'] }]);
    t.writeTodo();
    const plan = arm(t, ['F-1.1']);
    t.story('F-1.1').ac = 'a different promise';
    expect(verdict(t, plan, 'F-1.1', t.writeTodo())).toMatchObject({ decision: 'rerun', code: 'STALE_GREEN', stale: true });
  });

  it('checkStory_dependencyWithProseOnlyFiles_makesTheDependentRerun', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['the main source file a in src'] }, { id: 'F-1.2', wave: 2, deps: 'F-1.1', files: ['src/b.js'] }]);
    t.writeTodo();
    const result = verdict(t, arm(t, ['F-1.2']), 'F-1.2');
    expect(result).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
    expect(result.reason).toContain('F-1.1');
  });

  it('hashStory_proseOnlyFiles_stillHashes', () => {
    const t = makeRepo([{ id: 'F-1.1', wave: 1, files: ['the main source file a in src'] }]);
    t.writeTodo();
    expect(t.hash('F-1.1')).toMatch(HEX64);
  });
});

describe('F4: the current gate receipt stands in when no history row was written', () => {
  const receiptFile = (extra = {}) => ({
    schema: gr.RECEIPT_SCHEMA, id: RID, status: 'passed', exitCode: 0, mode: 'normal', changedOnly: false, filter: null,
    treeHashStart: 'a'.repeat(64), treeHashEnd: 'a'.repeat(64), build: { status: 'passed', reused: false, closureHash: null },
    projects: [], test: { status: 'passed', passed: 3, failed: 0, skipped: 0, total: 3 }, ...extra,
  });
  // Since SF-2.5 writeReceipt also archives by id under gate-receipts/by-id; "no history row" means no history json file.
  const noHistory = t => expect(fs.existsSync(gr.historyDir(t.root)) ? fs.readdirSync(gr.historyDir(t.root)).filter(n => n.endsWith('.json')) : []).toEqual([]);

  it('checkStory_receiptFileMatchesAndNoHistoryRowExists_skips', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile());
    noHistory(t);
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED', stale: false });
  });

  it('checkStory_receiptFileWithNoProjectsAndANullClosureHash_skips_theToolkitsOwnShape', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile({ projects: [], build: { status: 'passed', reused: false, closureHash: null } }));
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1').decision).toBe('skip');
  });

  it('checkStory_receiptFileWithPassingProjects_skips', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile({ mode: 'full', projects: [{ name: 'one', status: 'passed' }, { name: 'two', status: 'passed', reused: true }] }));
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1').decision).toBe('skip');
  });

  it('checkStory_receiptFileHasAnotherId_isNoReceipt', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile({ id: 'ffffffffffff' }));
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_noReceiptFileAndNoHistory_isNoReceipt', () => {
    const t = makeRepo();
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_receiptFileThatIsNotJson_isNoReceipt', () => {
    const t = makeRepo();
    fs.mkdirSync(path.dirname(gr.receiptPath(t.root)), { recursive: true });
    fs.writeFileSync(gr.receiptPath(t.root), '{ not json');
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it.each([
    ['status failed', { status: 'failed', exitCode: 1 }],
    ['status interrupted', { status: 'interrupted' }],
    ['exit code 1 with status passed', { exitCode: 1 }],
    ['change-scoped', { changedOnly: true }],
    ['filtered', { filter: 'unit' }],
    ['unknown mode', { mode: 'partial' }],
    ['tree changed during the run', { treeHashEnd: 'b'.repeat(64) }],
    ['no tree hash', { treeHashStart: null, treeHashEnd: null }],
    ['build failed', { build: { status: 'failed' } }],
    ['test leg failed', { test: { status: 'failed' } }],
    ['a project failed', { projects: [{ name: 'one', status: 'passed' }, { name: 'two', status: 'failed' }] }],
    ['a project was not run', { projects: [{ name: 'one', status: 'not-run' }] }],
    ['unknown schema', { schema: 99 }],
  ])('checkStory_receiptFile_%s_reruns', (_label, extra) => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile(extra));
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_receiptFilePassedButAHistoryRecordOfTheSameIdFailed_reruns', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile());
    t.history([record(RID, 'failed')]);
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_receiptFileFailedButTheHistoryRecordPassed_reruns', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile({ status: 'failed', exitCode: 1 }));
    t.history([record(RID)]);
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_receiptFilePassedButTheHistoryDirectoryHoldsJunk_reruns', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile());
    fs.mkdirSync(gr.historyDir(t.root), { recursive: true });
    fs.writeFileSync(path.join(gr.historyDir(t.root), 'junk-00000000.json'), 'not json');
    expect(verdict(t, planFor(t, 'F-1.1'), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('cli_receiptFileMatchesAndNoHistoryRow_exitsZero', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptFile());
    t.write('docs/.output/plans/261118-1200-run-todo-fixture.md', planFor(t, 'F-1.1'));
    const result = cli(t, ['check', t.todoPath, 'F-1.1']);
    expect(result.status).toBe(0);
    expect(JSON.parse(result.stdout)).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });
});

