describe('F8: unfinished and external dependencies are part of the checkpoint', () => {
  const stories = () => [
    { id: 'F-1.1', wave: 1, files: ['src/a.js'] },
    { id: 'F-1.2', wave: 2, deps: 'F-1.1', files: ['src/b.js'] },
    { id: 'F-1.3', wave: 3, deps: 'F-1.2', files: ['src/c.js'] },
  ];

  it.each([['[ ]'], ['[>]'], ['[!]'], ['[~]']])('checkStory_localDependencyMarked_%s_makesTheDependentRerun', (marker) => {
    const t = makeRepo(stories());
    const plan = arm(t, ['F-1.2']);
    t.story('F-1.1').status = marker;
    const result = verdict(t, plan, 'F-1.2', t.writeTodo());
    expect(result).toMatchObject({ decision: 'rerun', code: 'DEP_NOT_DONE', stale: false });
    expect(result.reason).toContain('F-1.1');
  });

  it('checkStory_transitiveDependencyNotDone_makesTheDependentRerun', () => {
    const t = makeRepo(stories());
    const plan = arm(t, ['F-1.3']);
    t.story('F-1.1').status = '[>]';
    const result = verdict(t, plan, 'F-1.3', t.writeTodo());
    expect(result).toMatchObject({ decision: 'rerun', code: 'DEP_NOT_DONE' });
    expect(result.reason).toContain('F-1.1');
  });

  it('checkStory_everyDependencyDone_stillSkips', () => {
    const t = makeRepo(stories());
    expect(verdict(t, arm(t, ['F-1.3']), 'F-1.3')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_dependencyNotDoneAndItsFileChanged_isStaleGreenFirst', () => {
    const t = makeRepo(stories());
    const plan = arm(t, ['F-1.2']);
    t.story('F-1.1').status = '[ ]';
    t.write('src/a.js', '// a edited\n');
    expect(verdict(t, plan, 'F-1.2', t.writeTodo())).toMatchObject({ code: 'STALE_GREEN', stale: true });
  });

  describe('a dependency in another TODO', () => {
    const external = (files = ['src/ext.js'], extra = {}) => todoOf([{ id: 'X-9.1', wave: 1, files, ...extra }]);
    const mine = () => makeRepo([{ id: 'F-1.1', wave: 2, deps: 'X-9.1', files: ['src/a.js'] }]);
    const check = (t, plan, ext) => sc().checkStory({ root: t.root, todoText: t.todo(), planText: plan, id: 'F-1.1', external: ext });
    const hashWith = (t, ext) => {
      const r = sc().hashStory({ root: t.root, todoText: t.todo(), id: 'F-1.1', external: ext });
      expect(r.ok, r.reason).toBe(true);
      return r.hash;
    };

    it('checkStory_externalDependencyNotSupplied_rerunsWithExternalDep', () => {
      const t = mine();
      t.write('src/ext.js', '// ext\n');
      const result = verdict(t, arm(t, ['F-1.1']), 'F-1.1');
      expect(result).toMatchObject({ decision: 'rerun', code: 'EXTERNAL_DEP', stale: false });
      expect(result.reason).toContain('X-9.1');
    });

    it('hashStory_externalDependencyNotSupplied_stillHashes', () => {
      const t = mine();
      expect(t.hash('F-1.1')).toMatch(HEX64);
    });

    it('checkStory_externalDependencySuppliedAndDone_skips', () => {
      const t = mine();
      t.write('src/ext.js', '// ext\n');
      const ext = [external()];
      const plan = waveLog(line(`F-1.1=${hashWith(t, ext).slice(0, 12)}@${RID}`));
      t.history([record(RID)]);
      expect(check(t, plan, ext)).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
    });

    it('hashStory_supplyingTheExternalDependency_changesTheHash', () => {
      const t = mine();
      expect(hashWith(t, [external()])).not.toBe(t.hash('F-1.1'));
    });

    it('checkStory_externalDependencyFileEdited_isStaleGreen', () => {
      const t = mine();
      t.write('src/ext.js', '// ext v1\n');
      const ext = [external()];
      const plan = waveLog(line(`F-1.1=${hashWith(t, ext).slice(0, 12)}@${RID}`));
      t.history([record(RID)]);
      t.write('src/ext.js', '// ext v2\n');
      expect(check(t, plan, ext)).toMatchObject({ decision: 'rerun', code: 'STALE_GREEN', stale: true });
    });

    it('checkStory_externalDependencyBlockEdited_isStaleGreen', () => {
      const t = mine();
      const plan = waveLog(line(`F-1.1=${hashWith(t, [external()]).slice(0, 12)}@${RID}`));
      t.history([record(RID)]);
      expect(check(t, plan, [external(['src/ext.js'], { ac: 'a changed promise' })])).toMatchObject({ code: 'STALE_GREEN', stale: true });
    });

    it('checkStory_externalDependencyNotDone_rerunsWithDepNotDone', () => {
      const t = mine();
      const plan = waveLog(line(`F-1.1=${hashWith(t, [external()]).slice(0, 12)}@${RID}`));
      t.history([record(RID)]);
      const result = check(t, plan, [external(['src/ext.js'], { status: '[>]' })]);
      expect(result).toMatchObject({ decision: 'rerun', code: 'DEP_NOT_DONE' });
      expect(result.reason).toContain('X-9.1');
    });

    it('checkStory_externalDependencyWithProseOnlyFiles_reruns', () => {
      const t = mine();
      const ext = [external(['an unresolved prose entry'])];
      const plan = waveLog(line(`F-1.1=${hashWith(t, ext).slice(0, 12)}@${RID}`));
      t.history([record(RID)]);
      expect(check(t, plan, ext)).toMatchObject({ decision: 'rerun', code: 'FILES_UNRESOLVED' });
    });

    it('checkStory_storyThatOnlyTheExternalTodoHolds_isUnknown', () => {
      const t = mine();
      const result = sc().checkStory({ root: t.root, todoText: t.todo(), planText: '', id: 'X-9.1', external: [external()] });
      expect(result).toMatchObject({ decision: 'rerun', code: 'UNKNOWN_STORY' });
    });

    it('checkStory_externalTextThatIsNotAString_isIgnoredAndReruns', () => {
      const t = mine();
      expect(check(t, arm(t, ['F-1.1']), [42, null])).toMatchObject({ decision: 'rerun', code: 'EXTERNAL_DEP' });
    });

    it('cli_depsFrom_suppliesTheSiblingTodoForHashAndCheck', () => {
      const t = mine();
      t.write('src/ext.js', '// ext\n');
      const sibling = path.join(t.root, 'docs', 'TODO_sibling.md');
      fs.writeFileSync(sibling, external());
      const hashed = cli(t, ['hash', t.todoPath, 'F-1.1', '--deps-from', sibling]);
      expect(hashed.status).toBe(0);
      expect(hashed.stdout.trim()).toBe(hashWith(t, [external()]));
      t.history([record(RID)]);
      t.write('docs/.output/plans/261118-1200-run-todo-fixture.md', waveLog(line(`F-1.1=${hashed.stdout.trim().slice(0, 12)}@${RID}`)));
      const without = cli(t, ['check', t.todoPath, 'F-1.1']);
      expect(without.status).toBe(1);
      expect(JSON.parse(without.stdout).code).toBe('STALE_GREEN');
      const withSibling = cli(t, ['check', t.todoPath, 'F-1.1', '--deps-from', sibling]);
      expect(withSibling.status).toBe(0);
      expect(JSON.parse(withSibling.stdout)).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
    });

    it('cli_depsFromUnreadableFile_hashExitsOneAndCheckReruns', () => {
      const t = mine();
      const missing = path.join(t.root, 'docs', 'NO_SUCH_SIBLING.md');
      const hashed = cli(t, ['hash', t.todoPath, 'F-1.1', '--deps-from', missing]);
      expect(hashed.status).toBe(1);
      expect(hashed.stdout).not.toMatch(/[0-9a-f]{64}/);
      const checked = cli(t, ['check', t.todoPath, 'F-1.1', '--deps-from', missing]);
      expect(checked.status).toBe(1);
      expect(JSON.parse(checked.stdout).decision).toBe('rerun');
    });

    it.each([
      ['--deps-from without a value', ['check', 'TODO.md', 'F-1.1', '--deps-from']],
      ['--deps-from followed by a flag', ['check', 'TODO.md', 'F-1.1', '--deps-from', '--plan']],
      ['--plan given twice', ['check', 'TODO.md', 'F-1.1', '--plan', 'a.md', '--plan', 'b.md']],
      ['hash with --deps-from and no value', ['hash', 'TODO.md', 'F-1.1', '--deps-from']],
    ])('cli_%s_exitsTwo', (_label, args) => {
      const t = mine();
      expect(cli(t, args).status).toBe(2);
    });
  });
});

// ── SF-2.5: older receipts stay checkable through the by-id archive (wave 2 review F4) ──

describe('SF-2.5 older receipts', () => {
  const A = RID;
  const B = 'bbbbbbbbbbbb';
  const C = 'cccccccccccc';
  const receiptOf = (id, extra = {}) => ({
    schema: gr.RECEIPT_SCHEMA, id, status: 'passed', exitCode: 0, mode: 'normal', changedOnly: false, filter: null,
    treeHashStart: 'a'.repeat(64), treeHashEnd: 'a'.repeat(64), build: { status: 'passed', reused: false, closureHash: null },
    projects: [], test: { status: 'passed', passed: 3, failed: 0, skipped: 0, total: 3 }, ...extra,
  });
  const archiveOf = (t, id) => path.join(gr.historyDir(t.root), 'by-id', `${id}.json`);
  const noHistoryJson = t => expect(fs.existsSync(gr.historyDir(t.root)) ? fs.readdirSync(gr.historyDir(t.root)).filter(n => n.endsWith('.json')) : []).toEqual([]);
  /** Three gate runs through writeReceipt: A (the receipt the checkpoint names), then B, then C (the current one). */
  const threeRuns = (t, aExtra = {}) => {
    gr.writeReceipt(t.root, receiptOf(A, aExtra));
    gr.writeReceipt(t.root, receiptOf(B));
    gr.writeReceipt(t.root, receiptOf(C));
  };

  it('checkStory_checkpointNamesAReceiptTwoGateRunsOld_stillResolvesAndSkips', () => {
    const t = makeRepo();
    threeRuns(t);
    noHistoryJson(t);
    expect(gr.readReceipt(t.root).id).toBe(C);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED', stale: false });
  });

  it('checkStory_theCurrentAndTheMiddleReceiptsStillSkipToo', () => {
    const t = makeRepo();
    threeRuns(t);

    expect(verdict(t, planFor(t, 'F-1.1', B), 'F-1.1').decision).toBe('skip');
    expect(verdict(t, planFor(t, 'F-1.1', C), 'F-1.1').decision).toBe('skip');
  });

  it('cli_checkpointNamingAReceiptTwoRunsOld_exitsZero', () => {
    const t = makeRepo();
    threeRuns(t);
    t.write('docs/.output/plans/261118-1200-run-todo-fixture.md', planFor(t, 'F-1.1', A));

    const result = cli(t, ['check', t.todoPath, 'F-1.1']);

    expect(result.status).toBe(0);
    expect(JSON.parse(result.stdout)).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_anOldReceiptThatFailed_isArchivedAndForcesARerun', () => {
    const t = makeRepo();
    threeRuns(t, { status: 'failed', exitCode: 1 });

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it.each([
    ['status interrupted', { status: 'interrupted' }],
    ['status running', { status: 'running' }],
    ['exit code 1 with status passed', { exitCode: 1 }],
    ['change-scoped', { changedOnly: true }],
    ['filtered', { filter: 'unit' }],
    ['unknown mode', { mode: 'partial' }],
    ['tree changed during the run', { treeHashEnd: 'b'.repeat(64) }],
    ['no tree hash', { treeHashStart: null, treeHashEnd: null }],
    ['build failed', { build: { status: 'failed' } }],
    ['test leg failed', { test: { status: 'failed' } }],
    ['a project failed', { projects: [{ name: 'one', status: 'passed' }, { name: 'two', status: 'failed' }] }],
    ['a project was not run', { projects: [{ name: 'one', status: 'not-run' }] }],
    ['unknown schema', { schema: 99 }],
  ])('checkStory_archivedReceipt_%s_reruns_withTheSameCompletePassRulesAsTheCurrentReceipt', (_label, extra) => {
    const t = makeRepo();
    threeRuns(t, extra);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_archiveMissingForAnOldReceipt_isNoReceipt', () => {
    const t = makeRepo();
    threeRuns(t);
    fs.rmSync(archiveOf(t, A));

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_receiptThatWasNeverWritten_isNoReceipt', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptOf(B));
    gr.writeReceipt(t.root, receiptOf(C));

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_archiveFileHoldingAnotherReceipt_isNoReceipt', () => {
    const t = makeRepo();
    threeRuns(t);
    fs.copyFileSync(archiveOf(t, B), archiveOf(t, A));

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_archiveFileThatIsNotJson_isNoReceipt', () => {
    const t = makeRepo();
    threeRuns(t);
    fs.writeFileSync(archiveOf(t, A), '{ not json');

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_passedArchiveButAFailedHistoryRowOfTheSameId_reruns', () => {
    const t = makeRepo();
    threeRuns(t);
    t.history([record(A, 'failed')]);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_passedArchiveAndAPassedHistoryRowOfTheSameId_skips', () => {
    const t = makeRepo();
    threeRuns(t);
    t.history([record(A)]);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_historyRowAloneStillResolvesAReceiptForAProjectThatNeverWroteAnArchive', () => {
    const t = makeRepo();
    t.history([record(A)]);
    expect(gr.hasArchive(t.root)).toBe(false);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  // m8: a history row is one project's result. Once the gate keeps an archive, a receipt that is neither current nor
  // archived (pruned, or its archive write failed) cannot be judged whole, so a surviving passing row must not skip it.
  it('checkStory_m8_partialHistoryRowForAnArchivedProjectsPrunedReceipt_reruns', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptOf(C));
    t.history([record(A)]);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
  });

  it('checkStory_m8_aWholeRunThatFailedInAnotherProject_withOnlyThisProjectsPassingRowLeft_reruns', () => {
    const t = makeRepo();
    // The run A failed overall (another project); its archive entry was pruned; this project's own row still says passed.
    gr.writeReceipt(t.root, receiptOf(B));
    gr.writeReceipt(t.root, receiptOf(C));
    t.history([record(A, 'passed', { name: 'proj' })]);
    expect(gr.archivedReceipt(t.root, A)).toBeNull();

    const result = verdict(t, planFor(t, 'F-1.1', A), 'F-1.1');

    expect(result).toMatchObject({ decision: 'rerun', code: 'NO_RECEIPT' });
    expect(result.reason).toMatch(/partial gate history row/);
  });

  it('checkStory_m8_aFailedReceiptInTheFailureRing_isRecognisedAsNotPassed', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptOf(A, { status: 'failed', exitCode: 1 }));
    gr.writeReceipt(t.root, receiptOf(B));
    gr.writeReceipt(t.root, receiptOf(C));
    t.history([record(A)]);

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_m8_aWholeReceiptStillSkipsWhenItsOwnRingEntryIsPresent_evenAfterManyFailedRuns', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptOf(A));
    for (let i = 0; i < 40; i += 1) gr.writeReceipt(t.root, receiptOf(`f${String(i).padStart(11, '0')}`, { status: 'failed', exitCode: 1 }));
    gr.writeReceipt(t.root, receiptOf(C));

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'skip', code: 'UNCHANGED' });
  });

  it('checkStory_theCurrentReceiptThatFailed_winsOverASupersededPassedArchiveOfTheSameId', () => {
    const t = makeRepo();
    gr.writeReceipt(t.root, receiptOf(A));
    // The gate rewrites the same id as the run progresses; the current file is the freshest word on that id.
    fs.writeFileSync(gr.receiptPath(t.root), JSON.stringify(receiptOf(A, { status: 'failed', exitCode: 1 })));

    expect(verdict(t, planFor(t, 'F-1.1', A), 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'RECEIPT_NOT_PASSED' });
  });

  it('checkStory_theArchiveDoesNotWeakenTheOtherChecks_aStaleGreenStillReruns', () => {
    const t = makeRepo();
    threeRuns(t);
    const plan = planFor(t, 'F-1.1', A);
    t.write('src/a.js', '// a v2\n');

    expect(verdict(t, plan, 'F-1.1')).toMatchObject({ decision: 'rerun', code: 'STALE_GREEN', stale: true });
  });
});

// ── SF-2.5: /run-todo checkpoint wiring (Main Agent authored pins) ─────────────────────────────
describe('SF-2.5 run-todo checkpoint wiring', () => {
  const WF = path.resolve(__dirname, '../../skills/run-todo/references/workflow.md');
  const wf = () => fs.readFileSync(WF, 'utf8');

  it("Step 8d's wave log entry carries the Story checkpoints line in the seam format", () => {
    const t = wf();
    const entry = t.slice(t.indexOf('**8d. Update the execution plan file**'), t.indexOf('**8e.'));
    expect(entry).toContain('- **Story checkpoints:** {ID}={hash12}@{receiptId}');
    expect(entry).toContain('node .claude/core/story-checkpoint.js hash "{TODO_PATH}" {ID}');
  });

  it('the line written per the template parses with parseCheckpoints', () => {
    const sc = require('../story-checkpoint');
    const map = sc.parseCheckpoints('- **Story checkpoints:** SF-1.1=abcdef012345@a1a2b3c4d5e6, SF-1.2=0123456789ab@a1a2b3c4d5e6\n');
    expect(map.get('SF-1.1')).toEqual({ hash12: 'abcdef012345', receiptId: 'a1a2b3c4d5e6' });
    expect(map.get('SF-1.2')).toEqual({ hash12: '0123456789ab', receiptId: 'a1a2b3c4d5e6' });
  });

  it('Verification Plan rows are keyed per story', () => {
    const t = wf();
    expect(t).toContain('| Wave | Story | Changed behavior and AC |');
  });

  it('resume checks every [x] story with story-checkpoint check, re-dispatches only rerun stories and reports stale greens', () => {
    const t = wf();
    const resume = t.slice(t.indexOf('### 3. Check for existing execution plan'), t.indexOf('### 4. Owner decisions'));
    expect(resume).toContain('node .claude/core/story-checkpoint.js check "{TODO_PATH}" {story ID} --plan');
    expect(resume).toMatch(/re-dispatch that story only/i);
    expect(resume).toContain('STALE_GREEN');
  });

  it('creates no per-story file and no new status column', () => {
    const t = wf();
    const resume = t.slice(t.indexOf('### 3. Check for existing execution plan'), t.indexOf('### 4. Owner decisions'));
    expect(resume).toMatch(/No per-story file or status column/);
  });
});

// ── Wave 6 review M3 M4 m7 m9: how a resume uses the checkpoints ────────────────────────────────────────────
describe('Wave 6 review resume pins', () => {
  const WF = path.resolve(__dirname, '../../skills/run-todo/references/workflow.md');
  const wf = () => fs.readFileSync(WF, 'utf8');
  const resume = () => {
    const t = wf();
    return t.slice(t.indexOf('### 3. Check for existing execution plan'), t.indexOf('### 4. Owner decisions'));
  };

  it('M4_resumeChecksOnlyTheStoriesThisPlanCheckpointed_andKeepsTheMarkerOfAStoryDoneElsewhere', () => {
    const r = resume();
    expect(r).toMatch(/check each `\[x\]` story that this plan checkpointed[^\n]*the ID before `=`[^\n]*`\*\*Story checkpoints:\*\*` lines/);
    expect(r).toMatch(/A `\[x\]` story that no checkpoint line names was finished outside this plan/);
    expect(r).toMatch(/keep its marker, run no `check` for it \(it could only say `NO_CHECKPOINT`\) and list it in the Resume Point as `done elsewhere, not rechecked`/);
    expect(r).not.toMatch(/check every story already marked `\[x\]`/);
  });

  it('M4_aRerunStoryIsResetToPendingBeforeStepOne_runsInDependencyOrder_andStepOneAcceptsIt', () => {
    const r = resume();
    expect(r).toMatch(/in the next wave, in dependency order \(a dependent reported stale after an upstream rerun runs after it\)/);
    expect(r).toMatch(/set it back to `\[ \]` in the TODO, AC ticks cleared, before Step 1's pre-wave check, which expects `\[ \]`/);
    const t = wf();
    const step1 = t.slice(t.indexOf('#### Step 1: Pre-wave check'), t.indexOf('#### Step 2: Assemble context packages'));
    expect(step1).toMatch(/set back to `\[ \]` by a checkpoint rerun/);
  });

  it('M4_theSkipAndRerunReadingOfTheExitCodesIsStillStated', () => {
    const r = resume();
    expect(r).toMatch(/Exit 0 \(`skip`\) means the story's inputs/);
    expect(r).toMatch(/Exit 1 \(`rerun`\) on a checkpointed story means re-dispatch that story only/);
  });

  it('M4_theNoCheckpointCodeIsWhatTheHelperReturnsForAStoryTheLogDoesNotName', () => {
    const t = makeRepo();
    // F-1.1 is [x] and its plan names no checkpoint for it: the helper says NO_CHECKPOINT, which the workflow keeps as done.
    const result = verdict(t, waveLog(line(entry(t, 'F-1.4'))), 'F-1.1');
    expect(result).toMatchObject({ decision: 'rerun', code: 'NO_CHECKPOINT' });
  });

  it('m9_aStaleGreenFromALaterStoriesEditCanBeAcceptedAndReRecorded_withALaterLineWinning', () => {
    const r = resume();
    expect(r).toMatch(/A `STALE_GREEN` whose only changed input is a file that a later done story of this plan legitimately edited/);
    expect(r).toMatch(/`stale from a later story's edit, accepted`/);
    expect(r).toMatch(/re-record the checkpoint with the new `hash` in the next wave's `\*\*Story checkpoints:\*\*` line \(a later line wins\)/);
    const t = makeRepo();
    const plan = `${arm(t, ['F-1.1'])}\n### Wave 2\n${line(`F-1.1=${'0'.repeat(12)}@${RID}`)}\n`;
    // a later line for the same id wins (malformed or not): parseCheckpoints keeps the last one
    expect(sc().parseCheckpoints(plan).get('F-1.1')).toEqual({ hash12: '0'.repeat(12), receiptId: RID });
  });

  it('m7_aWaveCommittedUnderTheAuditedSkipOmitsItsCheckpointLine', () => {
    const t = wf();
    const entry8d = t.slice(t.indexOf('**8d. Update the execution plan file**'), t.indexOf('**8e.'));
    expect(entry8d).toMatch(/Omit the line for a wave committed under `SHIP_CHECK_SKIP` or in summary mode: it has no receipt to name, and a resume then treats its stories as done elsewhere \(kept, not rechecked\)/);
    expect(resume()).toMatch(/a wave committed under the audited skip/);
  });
});
